    Assertions.assertEquals(124, registers1.getAddress());
    Assertions.assertEquals(62, registers1.getNumberOfElements());
    // Prepare the results as we got them on the wire.
    Map<PlcReadRequest, BaseOptimizer.SubResponse<PlcReadResponse>> readResponses = new HashMap<>();
    readResponses.put(firstRequest, new BaseOptimizer.SubResponse<>(new DefaultPlcReadResponse(firstRequest, Map.of("coils0", new DefaultPlcResponseItem<>(PlcResponseCode.OK, new PlcRawByteArray(Hex.decodeHex("3060480c00c084000000000000000000000000000000")))))));
    readResponses.put(secondRequest, new BaseOptimizer.SubResponse<>(new DefaultPlcReadResponse(secondRequest, Map.of("registers0", new DefaultPlcResponseItem<>(PlcResponseCode.OK, new PlcRawByteArray(Hex.decodeHex("")))))));
    readResponses.put(thirdRequest, new BaseOptimizer.SubResponse<>(new DefaultPlcReadResponse(thirdRequest, Map.of("registers1", new DefaultPlcResponseItem<>(PlcResponseCode.OK, new PlcRawByteArray(Hex.decodeHex("a75cbc11000000007620bc26000000002f833f3c0000000086593f38000000005c293f0f0000000013aabc50000000003ffbbc8700000000da513f3b00000000c7113f3a0000000051ec3f3800000000a75cbc11000000007620bca60000000016873ed900000000ebee3ec000000000000000000000000044e5bc3b")))))));
    ////////////////////////////////////////////////////////////////////////////////////////////////////////////////
    // Process the responses
    ////////////////////////////////////////////////////////////////////////////////////////////////////////////////
    PlcReadResponse readResponse = sut.processReadResponses(readRequest, readResponses, mockContext);
    // Check if there were no invalid items
    List<String> failedTags = readResponse.getTagNames().stream().filter(tagName -> readResponse.getResponseCode(tagName) != PlcResponseCode.OK).collect(Collectors.toList());
    failedTags.forEach(failedTag -> Assertions.fail("Field " + failedTag + "failed."));
    // Check if the returned values match the expected ones
    for (String name : input.keySet()) {
        String[] data = input.get(name);
        String readValue = readResponse.getString(name);
        Assertions.assertEquals(data[1], readValue);
    }
